pub static CONTRACT: Contract = Contract {
    id: ORIGIN,
    display_name: "Kotlin",
    version: Version::new(0, 2, 0),
    produces_artifacts: false,
    summary: "Reads Kotlin source, next to any Java beside it, and writes class files through \
              the Java compiler's own writer, without a kotlinc anywhere.",
    inputs: &["kotlin.source", "java.source", "jvm.class"],
    outputs: &["jvm.class"],
    required_capabilities: &[Capability::Cache, Capability::TempStorage],
    forbidden_capabilities: &[
        Capability::Network,
        Capability::Internet,
        Capability::ProcessExec,
        Capability::KeyAccess,
        Capability::SensitiveOutput,
    ],
    non_responsibilities: &[
        "Converting class files to DEX; that is another step's work.",
        "Packaging or signing anything.",
        "Resolving dependencies. What it may call, it is handed.",
    ],
};

pub struct KotlinPlugin;

pub static PLUGIN: KotlinPlugin = KotlinPlugin;

impl Plugin for KotlinPlugin {
    fn contract(&self) -> &'static Contract {
        &CONTRACT
    }

    fn execute(&self, _ctx: &mut Context<'_>) -> Result<Outcome, Diagnostic> {
        Err(at(
            "EK300",
            0,
            0,
            "Kotlin compiles through the build, not through this plugin surface.",
        )
        .with_suggestion(
            "The plugin surface has no request to compile and nowhere to put what comes out.",
        ))
    }
}

pub fn parse_prelude() -> Result<Vec<(String, tree::File)>, Diagnostic> {
    let mut out = Vec::new();
    for (label, text) in prelude::FILES.iter().chain(prelude::LIBRARY) {
        let file = parse::file(text, label)?;
        out.push((format!("<prelude>/{label}"), file));
    }
    Ok(out)
}

pub fn compile_mixed(
    kotlin: &[(String, String)],
    java_sources: &[(String, String)],
    classpath: &crate::compilers::java::Classpath,
    jars: Vec<Vec<u8>>,
) -> Result<Vec<(String, Vec<u8>)>, Diagnostic> {
    let (all, seen) = lower_mixed(kotlin, java_sources, classpath, jars)?;
    crate::compilers::java::compile_units_together(all, &seen)
}

pub fn lower_mixed(
    kotlin: &[(String, String)],
    java_sources: &[(String, String)],
    classpath: &crate::compilers::java::Classpath,
    jars: Vec<Vec<u8>>,
) -> Result<
    (
        Vec<(String, crate::compilers::java::Unit)>,
        crate::compilers::java::Classpath,
    ),
    Diagnostic,
> {
    use crate::compilers::java;
    let mut java_units: Vec<(String, java::Unit)> = Vec::new();
    for (label, text) in java_sources {
        let stem = label
            .rsplit(['/', '\\'])
            .next()
            .and_then(|held| held.strip_suffix(".java"))
            .map(str::to_string);
        let units =
            java::parse_as(text, stem.as_deref()).map_err(|error| labelled(error, label))?;
        let source = label.rsplit(['/', '\\']).next().map(str::to_string);
        for mut unit in units {
            unit.source.clone_from(&source);
            java_units.push((label.clone(), unit));
        }
    }
    let mut parsed = Vec::new();
    for (label, text) in kotlin {
        let file = parse::file(text, label).map_err(|error| labelled(error, label))?;
        parsed.push((label.clone(), file));
    }
    let mut for_java = java_units.clone();
    if !java_units.is_empty() {
        for (label, file) in &parsed {
            let text = shells_of(file);
            if text.trim().is_empty() {
                continue;
            }
            if let Ok(units) = java::parse(&text) {
                for unit in units {
                    for_java.push((label.clone(), unit));
                }
            }
        }
    }
    let seen = java::units_seen_together(for_java, classpath);
    let world = world::World::new(
        &seen,
        jars,
        java_units.iter().map(|(_, unit)| unit.clone()).collect(),
    );
    let mut compiler = lower::Compiler::new(&world);
    let prelude = parse_prelude()?;
    compiler.prelude_files = prelude.len();
    for (label, file) in prelude {
        compiler.add_file(&label, file);
    }
    for (label, file) in parsed {
        compiler.add_file(&label, file);
    }
    compiler.declare_all()?;
    let units = compiler.lower_all()?;
    let mut all = java_units;
    all.extend(units);
    Ok((all, seen))
}

pub fn shells_of(file: &tree::File) -> String {
    let mut out = String::new();
    if !file.package.is_empty() {
        out.push_str(&format!("package {};\n", file.package.join(".")));
    }
    for declaration in &file.declarations {
        if let tree::Declaration::Class(class) = declaration {
            shell_of(class, true, &mut out);
        }
    }
    out
}

fn shell_of(class: &tree::Class, top: bool, out: &mut String) {
    if class.name.is_empty() {
        return;
    }
    let shape = match class.kind {
        tree::ClassKind::Interface => "interface",
        tree::ClassKind::Enum => "enum",
        tree::ClassKind::Annotation => "@interface",
        _ => "class",
    };
    let kept = if top
        || class.modifiers.has("inner")
        || matches!(
            class.kind,
            tree::ClassKind::Interface | tree::ClassKind::Enum | tree::ClassKind::Annotation
        ) {
        ""
    } else {
        "static "
    };
    let parameters = if class.type_parameters.is_empty()
        || matches!(
            class.kind,
            tree::ClassKind::Enum | tree::ClassKind::Annotation
        ) {
        String::new()
    } else {
        format!(
            "<{}>",
            class
                .type_parameters
                .iter()
                .map(|one| one.name.clone())
                .collect::<Vec<_>>()
                .join(", ")
        )
    };
    out.push_str(&format!(
        "public {kept}{shape} {}{parameters} {{\n",
        class.name
    ));
    for member in &class.members {
        if let tree::Declaration::Class(inner) = member {
            shell_of(inner, false, out);
        }
    }
    out.push_str("}\n");
}

pub fn labelled(mut error: Diagnostic, label: &str) -> Diagnostic {
    match error.location.as_mut() {
        Some(place) if place.file.is_empty() => place.file = label.to_string(),
        Some(_) => {}
        None => error.location = Some(crate::diag::Location::file(label)),
    }
    error.with_context(format!("File: {label}"))
}

